import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {WebSocket} from 'ws';
import {createServer} from './createServer.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '../types/sessionStore.js';

const exchange = async (store: SessionStore, enabled: boolean, request: object): Promise<Record<string, unknown>[]> => {
  const options = {
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'alice'}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
    ...(enabled ? {history: {enabled: true}} : {}),
  };
  const server = createServer(options);
  await server.start(0);
  const {port} = server.server.address() as AddressInfo;
  const socket = new WebSocket("'`ws://127.0.0.1:${port}/hal/ws`, [HAL_WS_SUBPROTOCOL, '"'token']);
  const frames: Record<string, unknown>[] = [];
  try {
    await new Promise<void>((resolve, reject) => {
      socket.on('error', reject);
      socket.on('message', raw => {
        const frame = JSON.parse(String(raw)) as Record<string, unknown>;
        if (frame.type === 'connected') {
          socket.send(JSON.stringify(request));
          socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
        } else if (frame.type === 'pong') resolve();
        else frames.push(frame);
      });
    });
    return frames;
  } finally {
    socket.terminate();
    await server.stop();
  }
};

describe('conversation list over WebSocket', () => {
  it('validates the list request and its composite cursor', () => {
    expect(validateMessage({type: 'list_conversations'})).toEqual({valid: true, data: {type: 'list_conversations'}});
    for (const limit of [0, 201, 1.5, '10']) {
      expect(validateMessage({type: 'list_conversations', limit})).toEqual(expect.objectContaining({valid: false, error: expect.stringMatching(/limit/i)}));
    }
    for (const before of ['not a date', {updatedAt: 'bad', sessionId: 'a'}, {updatedAt: '2026-01-01T00:00:00.000Z'}, {sessionId: 'a'}]) {
      expect(validateMessage({type: 'list_conversations', before})).toEqual(expect.objectContaining({valid: false, error: expect.stringMatching(/before/i)}));
    }
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'};
    expect(validateMessage({type: 'list_conversations', limit: 2, before, userId: 'bob'})).toEqual({valid: true, data: {type: 'list_conversations', limit: 2, before}});
  });

  it('answers with the authenticated user’s paged metadata and never another user’s', async () => {
    const store = new InMemorySessionStore();
    for (const [id, user, time] of [['a', 'alice', '2026-01-01T00:00:00.000Z'], ['b', 'alice', '2026-01-02T00:00:00.000Z'], ['c', 'alice', '2026-01-03T00:00:00.000Z'], ['secret', 'bob', '2026-01-04T00:00:00.000Z']]) {
      store.create(id, user).entries.push({role: 'user', content: 'private', timestamp: time});
    }
    const before = {updatedAt: '2026-01-04T00:00:00.000Z', sessionId: 'z'};
    const frames = await exchange(store, true, {type: 'list_conversations', userId: 'bob', limit: 2, before});
    expect(frames).toEqual([{type: 'conversation_list', conversations: expect.any(Array)}]);
    const rows = frames[0].conversations as Array<Record<string, unknown>>;
    expect(rows.map(row => row.sessionId)).toEqual(['c', 'b']);
    for (const row of rows) {
      expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
      expect(new Date(row.createdAt as string).toISOString()).toBe(row.createdAt);
      expect(new Date(row.updatedAt as string).toISOString()).toBe(row.updatedAt);
      expect(row.entryCount).toBe(1);
    }
  });

  it('reports unsupported when history is disabled or the store cannot list', async () => {
    const inner = new InMemorySessionStore();
    const noList: SessionStore = {create: (...args) => inner.create(...args), get: id => inner.get(id), delete: id => inner.delete(id), count: () => inner.count(), clear: () => inner.clear()};
    for (const [store, enabled] of [[inner, false], [noList, true]] as const) {
      expect(await exchange(store, enabled, {type: 'list_conversations'})).toEqual([expect.objectContaining({type: 'error', code: 'UNSUPPORTED'})]);
    }
  });
});
